type AssetManifest = {
	basePath: string;
	bundles: {
		name: string;
		assets: Record<string, unknown>;
	}[];
};

/**
 * GAME_MANIFEST — tells CoreController where assets live and
 * which bundle name to load at startup.
 *
 * The actual asset list is in:
 *   public/assets/demoslot/manifest.json
 *
 * That file is what PixiJS Assets.init() reads.
 * It is a real JSON file on disk, generated by assetpack — not TypeScript.
 *
 * When new assets are added:
 *   1. Add the file to raw-assets/demoslot/ and run npm run assets:build
 *   2. Add the entry to public/assets/demoslot/manifest.json
 *   Done — no TypeScript changes needed.
 */
export const GAME_MANIFEST: AssetManifest = {
	basePath: "/assets/demoslot",
	bundles: [
		{
			name: "ds-preload",
			assets: {} // actual assets defined in manifest.json on disk
		},
		{
			name: "ds-audio",
			assets: {} // loaded lazily via this.loadBundle("ds-audio")
		}
	]
};
